-- ══════════════════════════════════════════════════════════════════════════
-- 20260837_registry_seed.sql
-- DCIMe V2.1 — Stage 1: the parameter registry enters service.
--
-- Mechanically generated from src/config/mappings/excelMappings.ts and the site
-- blueprints, both of which were the only place these 736 destinations existed.
-- Copying them by machine rather than by hand meant the import introduced no
-- transcription errors of its own; the defects already in the mapping were
-- copied faithfully and are corrected in Stage 4, against a conformance test
-- that reads the real template headings rather than trusting either file.
--
-- excelMappings.ts has since been retired — the database is the source now, and
-- the generator that read it went with it. Every value is written out in full
-- below, and the original file remains in git history if a column index ever
-- needs re-deriving.
--
-- equipment_parameters held exactly one row in production, so
-- get_site_form_definition() returned nothing and the shift form has been driven
-- by the blueprint JSON all along. The registry was built and never loaded.
-- This migration loads it, from the same blueprint, so the two agree before the
-- blueprint is retired.
--
--   SITE_01: 324 captured · 221 not applicable · 572 excel cells · 70 unowned (reported, not inserted)
--   SITE_02: 115 captured · 34 not applicable · 164 excel cells · 0 unowned (reported, not inserted)
--
-- Requires 20260836 (capture_mode, parameter_excel_targets).
-- Idempotent: safe to re-run. Existing rows are never overwritten.
-- ══════════════════════════════════════════════════════════════════════════

-- ────────────────────────────────────────────────────────────────────────
-- SITE_01 — 324 captured · 221 not applicable · 572 excel cells
-- ────────────────────────────────────────────────────────────────────────
DO $seed$
DECLARE
  v_site uuid;
  v_equipment int;
  v_params int;
  v_targets int;
BEGIN
  SELECT id INTO v_site FROM public.sites WHERE site_code = 'SITE_01';
  IF v_site IS NULL THEN
    RAISE NOTICE 'SITE_01: not present in this database — skipped.'; RETURN;
  END IF;

  SELECT count(*) INTO v_equipment FROM public.equipment_registry WHERE site_uuid = v_site;
  IF v_equipment = 0 THEN
    -- equipment_parameters.equipment_id is FK-constrained to
    -- equipment_registry, so seeding parameters for a site whose assets
    -- have not been loaded would abort the whole migration.
    RAISE NOTICE 'SITE_01: no equipment in the registry — parameters skipped. Load equipment first.';
    RETURN;
  END IF;

  -- What a technician fills in today, lifted from SITE_01_blueprint.json.
  INSERT INTO public.equipment_parameters
    (equipment_id, parameter_name, display_label, data_type, input_type, frequency,
     carry_forward, default_value, is_constant, constant_value, capture_mode,
     display_order, is_required, is_active)
