  ) AS v(parameter_name, workbook, sheet_name, column_index, row_rule)
  -- Only for parameters that actually exist at this site, so a target can
  -- never point at a column with nothing behind it.
  WHERE EXISTS (SELECT 1 FROM public.equipment_parameters p
                  JOIN public.equipment_registry e ON e.equipment_id = p.equipment_id
                 WHERE p.parameter_name = v.parameter_name AND e.site_uuid = v_site)
  ON CONFLICT (site_uuid, parameter_name, workbook, sheet_name) DO UPDATE
     SET column_index = EXCLUDED.column_index, row_rule = EXCLUDED.row_rule;

  SELECT count(*) INTO v_params FROM public.equipment_parameters p
    JOIN public.equipment_registry e ON e.equipment_id = p.equipment_id
   WHERE e.site_uuid = v_site;
  SELECT count(*) INTO v_targets FROM public.parameter_excel_targets WHERE site_uuid = v_site;
  RAISE NOTICE 'SITE_02: % parameters, % excel targets', v_params, v_targets;
END $seed$;
